// Loads the shared furniture catalog generated by the website (npm run catalog).
using System;
using System.Collections.Generic;
using UnityEngine;

namespace RealTweak
{
    [Serializable]
    public class CatalogPart
    {
        public string s;          // box | cyl | sph
        public float x, y, z;     // part centre, web coordinates
        public float w, h, d;     // size (cylinders/spheres: diameters)
        public float rx, ry, rz;  // XYZ Euler degrees, web coordinates
        public float t;           // cylinder top/bottom ratio (0 = 1)
        public string c;          // "main" or #rrggbb
        public string m;          // material hint
    }

    [Serializable]
    public class CatalogItem
    {
        public string type, name, category, color, mount, tags;
        public float w, h, d, elev;
        public CatalogPart[] parts;
        public float[] path;      // staircase walking path (x,y,z triples, web item space)
    }

    [Serializable]
    class CatalogFile { public int version; public string[] categories; public CatalogItem[] items; }

    public static class Catalog
    {
        static Dictionary<string, CatalogItem> byType;
        static List<CatalogItem> items;
        static string[] categories;

        static void Load()
        {
            if (items != null) return;
            var asset = Resources.Load<TextAsset>("RealTweakCatalog");
            var file = asset != null ? JsonUtility.FromJson<CatalogFile>(asset.text) : null;
            items = new List<CatalogItem>(file?.items ?? Array.Empty<CatalogItem>());
            categories = file?.categories ?? Array.Empty<string>();
            byType = new Dictionary<string, CatalogItem>();
            foreach (var item in items) byType[item.type] = item;
            if (items.Count == 0) Debug.LogError("RealTweak: furniture catalog missing. Run `npm run catalog` in RealTweak_Website.");
        }

        public static IReadOnlyList<CatalogItem> Items { get { Load(); return items; } }
        public static IReadOnlyList<string> Categories { get { Load(); return categories; } }
        public static bool Has(string type) { Load(); return type != null && byType.ContainsKey(type); }

        /// <summary>Definition for a type; unknown (newer) types render as a neutral box so they are never lost.</summary>
        public static CatalogItem Get(string type)
        {
            Load();
            if (type != null && byType.TryGetValue(type, out var item)) return item;
            return new CatalogItem
            {
                type = type ?? "unknown", name = type ?? "Unknown", category = "Other", color = "#a4afa9", mount = "floor", w = 1, h = 1, d = 1,
                parts = new[] { new CatalogPart { s = "box", y = 0.5f, w = 1, h = 1, d = 1, c = "main", m = "" } },
            };
        }

        public static Color ParseColor(string hex, Color fallback)
        {
            return !string.IsNullOrEmpty(hex) && ColorUtility.TryParseHtmlString(hex, out var c) ? c : fallback;
        }
    }
}
